    var W = opt.W || 1.1, MAX = opt.MAX || 1.5, minH = opt.minH != null ? opt.minH : 0.05, prefix = opt.prefix || 'PNL';
    if (!Array.isArray(top)) top = [[0, +top], [L, +top]];
    var ops = [], i, j;
    for (i = 0; i < (openings || []).length; i++) {
      var o = openings[i], a0 = Math.max(0, o.a0), a1 = Math.min(L, o.a1), y0 = Math.max(0, o.y0), y1 = o.y1;
      if (a1 - a0 > EPS && y1 - y0 > EPS) ops.push({ a0: a0, a1: a1, y0: y0, y1: y1, kind: o.kind || 'window' });
    }
