        for (j = 0; j < cov.length; j++) if (cov[j].y0 <= r0 + EPS && cov[j].y1 >= r1 - EPS) { hole = cov[j]; break; }
        if (hole) { var hl = Math.min(r1, profMin(top, c0, c1)); if (hl > r0) holeArea += (c1 - c0) * (hl - r0); holes.push({ a0: r6(c0), a1: r6(c1), y0: r6(r0), y1: r6(r1), kind: hole.kind }); continue; }
        var role = 'pier';
